```cpp
void Leader::HandleCommissioningGet(Coap::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
{
    MeshCoP::Tlv tlv;
    uint16_t     offset = aMessage.GetOffset();
    uint8_t      tlvs[NetworkData::kMaxSize];  // 254 bytes
    uint8_t      length = 0;

    while (offset < aMessage.GetLength())
    {
        aMessage.Read(offset, sizeof(tlv), &tlv);

        if (tlv.GetType() == MeshCoP::Tlv::kGet)
        {
            length = tlv.GetLength();  // Can be 255 (0xFF)
            aMessage.Read(offset + sizeof(MeshCoP::Tlv), length, tlvs);  // Reads 255 bytes into 254-byte buffer!
            break;
        }

        offset += sizeof(tlv) + tlv.GetLength();
    }
    ...
}
```

The `tlvs` buffer is `uint8_t tlvs[NetworkData::kMaxSize]` where kMaxSize=254. But `length` comes from `tlv.GetLength()` which returns a `uint8_t`, so max value is 255. When a TLV with type=kGet (0x0D) has length=255, it reads 255 bytes into a 254-byte buffer, causing a 1-byte stack buffer overflow.

Now let me verify kGet's value and kMaxSize:

